------------------------------------------------------------
----- ROOT ID FUNCTION FOR: [Widget].[widgetID]
------------------------------------------------------------
IF OBJECT_ID('[higherlogic_vanilla].[fnWidgetwidgetID_GetRootID]', 'IF') IS NOT NULL
    DROP FUNCTION [higherlogic_vanilla].[fnWidgetwidgetID_GetRootID];
GO

CREATE FUNCTION [higherlogic_vanilla].[fnWidgetwidgetID_GetRootID]
(
    @RecordID nvarchar(450),
    @ParentID nvarchar(450)
)
RETURNS TABLE
AS
RETURN
(
    WITH CTE_RootParent AS (
        SELECT
            [name],
            [widgetID],
            [name] AS [RootParentID],
            0 AS [Depth]
        FROM
            [higherlogic_vanilla].[Widget]
        WHERE
            [name] = COALESCE(@ParentID, @RecordID)

        UNION ALL

        SELECT
            c.[name],
            c.[widgetID],
            c.[name] AS [RootParentID],
            p.[Depth] + 1 AS [Depth]
        FROM
            [higherlogic_vanilla].[Widget] c
        INNER JOIN
            CTE_RootParent p ON c.[name] = p.[widgetID]
        WHERE
            p.[Depth] < 100
    )
    SELECT TOP 1
        [RootParentID] AS RootID
    FROM
        CTE_RootParent
    WHERE
        [widgetID] IS NULL
    ORDER BY
        [RootParentID]
);
GO

